import 'dart:async';
import 'dart:convert';

import 'package:flutter/foundation.dart';
import 'package:flutter/gestures.dart';
import 'package:flutter/material.dart';
import 'package:webview_flutter/webview_flutter.dart';

import 'salah_models.dart';

// The owner's schematic 3D scene (docs/salah/salah-3d.md) in place of the pose
// pictures, which are stills of it. assets/salah3d holds the same scene the site
// runs: its salah-scene.js and three.min.js are generated by
// services/web/scripts/salah3d-app-assets.ts. Mirrors services/web/lib/salah-3d.ts.

/// The poses this build's scene can show; a newer course may name others
/// (they stay pictures).
const salahScenePoses = <String>{
  'qiyam',
  'takbir',
  'ruku',
  'itidal',
  'sujud',
  'jalsa',
  'sujud2',
  'tashahhud',
  'salam',
};

/// The scene of each step, from the still its picture is, or null where the
/// picture is all there is.
List<SalahMediaScene?> salahStepScenes(
  SalahCourseDocument document,
  List<SalahStep> steps,
) {
  SalahMediaScene? sceneOf(int index) =>
      index < 0 ? null : document.stepMedia(steps[index])?.scene;
  return <SalahMediaScene?>[
    for (var index = 0; index < steps.length; index++)
      () {
        final scene = sceneOf(index);
        if (scene == null || !salahScenePoses.contains(scene.pose)) return null;
        // One picture serves both prostrations; the second rises from the
        // sitting between them.
        if (scene.pose == 'sujud' &&
            scene.view == 'full' &&
            sceneOf(index - 1)?.pose == 'jalsa') {
          return const SalahMediaScene(pose: 'sujud2');
        }
        return scene;
      }(),
  ];
}

const salahSceneSpeeds = <double>[1, .75, .5];

/// The lesson's 3D scene: it runs on the current step when the device can,
/// and any failure leaves the stills for the rest of the visit. Each step
/// plays its pose once and holds the last frame; play then replays it.
/// Mirrors nextSalahScenePlayback in services/web/lib/salah-3d.ts.
class Salah3DController extends ChangeNotifier {
  bool _failed = false;
  bool _ready = false;
  bool _playing = true;
  bool _ended = false;
  double _speed = 1;
  int _replayCount = 0;

  bool get failed => _failed;
  bool get ready => _ready;

  /// Not paused; the pose may still have played to its end.
  bool get playing => _playing;

  /// The pose has played once and holds its last frame.
  bool get ended => _ended;

  /// The pose is moving: neither paused nor played to its end.
  bool get moving => _playing && !_ended;
  double get speed => _speed;

  /// Grows whenever the current pose should play again from its start.
  int get replayCount => _replayCount;

  void markReady() {
    if (_ready || _failed) return;
    _ready = true;
    notifyListeners();
  }

  void fail() {
    if (_failed) return;
    _failed = true;
    _ready = false;
    notifyListeners();
  }

  void markEnded() {
    if (_ended) return;
    _ended = true;
    notifyListeners();
  }

  /// The next step loads its own scene and plays its pose once, whether the
  /// last one was paused or had ended.
  void stepChanged() {
    if (!_ready && _playing && !_ended) return;
    _ready = false;
    _playing = true;
    _ended = false;
    notifyListeners();
  }

  void replay() {
    _playing = true;
    _ended = false;
    _replayCount++;
    notifyListeners();
  }

  /// Play after the end is a replay.
  void togglePlaying() {
    if (_ended) {
      replay();
      return;
    }
    _playing = !_playing;
    notifyListeners();
  }

  void cycleSpeed() {
    final next = salahSceneSpeeds.indexOf(_speed) + 1;
    _speed = salahSceneSpeeds[next % salahSceneSpeeds.length];
    notifyListeners();
  }
}

/// What the 3D view of one step is asked to show.
@immutable
class Salah3DViewConfig {
  const Salah3DViewConfig({
    required this.step,
    required this.view,
    required this.running,
    required this.foreground,
    required this.speed,
    required this.replayCount,
    required this.onReady,
    required this.onEnded,
    required this.onError,
  });

  /// A scene pose, for example `ruku`.
  final String step;

  /// `full`, or the `hand` or `back` close view.
  final String view;

  /// Playing, with the lesson the visible route.
  final bool running;

  /// The app is in the foreground. It changes while frames are off, so the
  /// view follows it without waiting for a rebuild.
  final ValueListenable<bool> foreground;
  final double speed;

  /// Changes when the pose should play again from its start.
  final int replayCount;
  final VoidCallback onReady;

  /// The pose has played once and holds its last frame.
  final VoidCallback onEnded;
  final ValueChanged<String> onError;
}

typedef Salah3DViewBuilder =
    Widget Function(BuildContext context, Salah3DViewConfig config);

/// The real view: the bundled page in a WebView. Tests replace it.
Widget buildSalah3DWebView(BuildContext context, Salah3DViewConfig config) =>
    Salah3DWebView(config: config);

/// The scene from assets/salah3d in a WebView, offline. Only the bundled page
/// may load; the page talks back through the `SalahBridge` channel.
class Salah3DWebView extends StatefulWidget {
  const Salah3DWebView({required this.config, super.key});

  final Salah3DViewConfig config;

  @override
  State<Salah3DWebView> createState() => _Salah3DWebViewState();
}

class _Salah3DWebViewState extends State<Salah3DWebView> {
  late final WebViewController _web;
  Timer? _timeout;
  var _shown = false;

  // Horizontal drags turn the figure and pinches zoom; vertical drags still
  // scroll the step.
  static final _gestures = <Factory<OneSequenceGestureRecognizer>>{
    // One factory per recognizer type, or the platform view asserts.
    Factory<HorizontalDragGestureRecognizer>(
      HorizontalDragGestureRecognizer.new,
    ),
    Factory<ScaleGestureRecognizer>(ScaleGestureRecognizer.new),
  };

  Salah3DViewConfig get _config => widget.config;

  bool get _running => _config.running && _config.foreground.value;
  bool? _applied;

  void _sync() {
    final running = _running;
    if (!_shown || running == _applied) return;
    _applied = running;
    _run(running ? 'salah.play()' : 'salah.pause()');
  }

  @override
  void initState() {
    super.initState();
    _config.foreground.addListener(_sync);
    _web = WebViewController()
      ..setJavaScriptMode(JavaScriptMode.unrestricted)
      ..setBackgroundColor(const Color(0xFFF1EDE4))
      ..addJavaScriptChannel('SalahBridge', onMessageReceived: _onMessage)
      ..setOnConsoleMessage((message) {
        if (kDebugMode) debugPrint('Salah 3D page: ${message.message}');
      })
      ..setNavigationDelegate(
        NavigationDelegate(
          onNavigationRequest: (request) =>
              request.url.startsWith('file:') ||
                  request.url.startsWith('about:')
              ? NavigationDecision.navigate
              : NavigationDecision.prevent,
          onWebResourceError: (error) {
            if (error.isForMainFrame ?? true) _config.onError('LOAD_FAILED');
          },
        ),
      );
    _timeout = Timer(const Duration(seconds: 20), () {
      if (!_shown) _config.onError('TIMEOUT');
    });
    unawaited(
      _web.loadFlutterAsset('assets/salah3d/index.html').catchError((_) {
        _config.onError('LOAD_FAILED');
      }),
    );
  }

  @override
  void didUpdateWidget(Salah3DWebView oldWidget) {
    super.didUpdateWidget(oldWidget);
    final old = oldWidget.config;
    if (old.foreground != _config.foreground) {
      old.foreground.removeListener(_sync);
      _config.foreground.addListener(_sync);
    }
    _sync();
    if (old.speed != _config.speed) _run('salah.setSpeed(${_config.speed})');
    if (old.replayCount != _config.replayCount) _run('salah.replay()');
    if (old.step != _config.step) {
      _run('salah.show(${jsonEncode(_config.step)})');
    }
  }

  @override
  void dispose() {
    _config.foreground.removeListener(_sync);
    _timeout?.cancel();
    _run('salah.dispose()');
    super.dispose();
  }

  void _run(String command) {
    unawaited(
      _web.runJavaScript('window.salah && $command').catchError((Object _) {}),
    );
  }

  void _onMessage(JavaScriptMessage message) {
    Object? decoded;
    try {
      decoded = jsonDecode(message.message);
    } on FormatException {
      return;
    }
    if (!mounted || decoded is! Map<String, Object?>) return;
    switch (decoded['type']) {
      case 'LOADED':
        _run(
          'salah.show(${jsonEncode(_config.step)}, ${_config.speed}, '
          '${jsonEncode(_config.view)})',
        );
      case 'READY':
        _timeout?.cancel();
        _shown = true;
        _sync();
        _config.onReady();
      case 'ENDED':
        _config.onEnded();
      case 'ERROR':
        _timeout?.cancel();
        _config.onError('${decoded['code']}');
    }
  }

  // Always drawn: a transparent WebView may not get animation frames. The
  // still covers it until the first frame is ready.
  @override
  Widget build(BuildContext context) => ExcludeSemantics(
    child: WebViewWidget(controller: _web, gestureRecognizers: _gestures),
  );
}
